    /*
     * Assign a Policy
     * 
     * @param	parentId	UUID
     * @param	assignment 	Policy 
     * @return	Claim
     */
    public Claim assignPolicy( UUID parentId, Policy assignment ) {
	    LOGGER.info("assigning Policy as " + assignment.toString() );

	    Claim parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Policy.class, assignment.getPolicyId());

	    // ------------------------------------------
		// assign the Policy to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPolicy( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

